  enrollmentId: string;
  learnerId: string;
  learnerName: string;
} & (
  | { status: 'issued'; certificateId: string; serialNumber: string }
  | { status: 'skipped'; reason: 'incomplete' | 'already_issued' | 'revoked' }
  | { status: 'failed'; reason: 'issuance_failed' }
);
export interface BulkIssuanceResponse {
  courseId: string;
  total: number;
  issued: number;
  skipped: number;
