import { useEffect, useRef, useState, type FormEvent } from 'react';
import { isBulkIssuanceResponse, isCourseListResponse, type BulkIssuanceResponse, type CourseOption } from '@training/shared';

const reasons = { incomplete: 'Course not completed', already_issued: 'Certificate already issued', revoked: 'Certificate previously revoked', issuance_failed: 'Issuance failed; retry this course' };
export function BulkIssuance({ token, onComplete }: { token: string; onComplete: () => void }) {
  const [courses, setCourses] = useState<CourseOption[]>([]);
  const [courseId, setCourseId] = useState('');
  const [courseState, setCourseState] = useState<'loading' | 'ready' | 'error' | 'unauthorized'>('loading');
  const [attempt, setAttempt] = useState(0);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState<BulkIssuanceResponse | null>(null);
  const submitting = useRef(false);
  const mounted = useRef(false);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
  useEffect(() => {
    if (!token) return;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10000);
    let active = true;
    setCourseState('loading');
    void fetch('/api/certificates/courses', { headers: { Authorization: `Bearer ${token}` }, signal: controller.signal })
      .then(async response => {
        if (response.status === 401) { if (active) setCourseState('unauthorized'); return; }
        if (!response.ok) throw new Error('Course request failed');
        const data: unknown = await response.json();
        if (!isCourseListResponse(data)) throw new Error('Invalid courses');
        if (active) { setCourses(data.items); setCourseState('ready'); }
      }).catch(() => { if (active) setCourseState('error'); }).finally(() => clearTimeout(timeout));
    return () => { active = false; controller.abort(); clearTimeout(timeout); };
  }, [token, attempt]);
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (submitting.current || !token || !courseId) return;
    submitting.current = true;
    setPending(true); setError(''); setResult(null);
    try {
      const response = await fetch('/api/certificates/bulk-issuance', { method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ courseId }) });
      if (!mounted.current) return;
      if (response.status === 400) throw new Error('The issuance request is invalid. Reload courses and select a course again. No certificates were issued.');
      if (response.status === 401) throw new Error('The admin token is invalid or no longer authorized.');
      if (response.status === 404) throw new Error('The selected course is no longer available. Reload courses and select again.');
      if (!response.ok) throw new Error('Unable to confirm issuance. Some certificates may have been issued. Retrying the course safely skips existing certificates.');
      const data: unknown = await response.json();
      if (!isBulkIssuanceResponse(data) || data.courseId !== courseId) throw new Error('Invalid issuance response. Some certificates may have been issued. Retrying safely skips existing certificates.');
      if (mounted.current) { setResult(data); onComplete(); }
    } catch (cause: unknown) {
      if (mounted.current) setError(cause instanceof Error && cause.message !== 'Failed to fetch' ? cause.message : 'Unable to confirm issuance. Some certificates may have been issued. Retrying safely skips existing certificates.');
    } finally {
      submitting.current = false;
      if (mounted.current) setPending(false);
    }
  }
  return <section aria-labelledby="bulk-issuance-heading">
    <h2 id="bulk-issuance-heading">Bulk issuance</h2>
    <p>Choose a course to issue certificates to all completed learners. Existing certificates, including revoked certificates, are skipped. Results stay available until you change course, token, or reload.</p>
    {!token ? <p>Supply an admin token above to choose a course.</p> : <>
      {courseState === 'loading' && <p role="status">Loading courses…</p>}
      {courseState === 'unauthorized' && <p role="alert">Supply a valid admin token to load courses.</p>}
      {courseState === 'error' && <p role="alert">Unable to load courses.</p>}
      <button type="button" disabled={pending || courseState === 'loading'} onClick={() => { setCourseId(''); setResult(null); setError(''); setAttempt(value => value + 1); }}>Reload courses</button>
      {courseState === 'ready' && (courses.length === 0 ? <p>No courses available.</p> : <form onSubmit={event => void submit(event)} className="controls" aria-busy={pending}>
        <label>Course<select value={courseId} disabled={pending} required onChange={event => { setCourseId(event.target.value); setResult(null); setError(''); }}>
          <option value="">Select a course</option>
          {courses.map(course => <option key={course.id} value={course.id}>{course.title}</option>)}
        </select></label>
        <button type="submit" disabled={pending || !courseId}>Issue to eligible learners</button>
      </form>)}
      <p role="status" aria-live="polite">{pending ? 'Issuing certificates… Keep this page open for results.' : result ? `Completed: ${result.issued} issued, ${result.skipped} skipped, ${result.failed} failed.` : ''}</p>
      {error && <p role="alert">{error}</p>}
      {result && (result.total === 0 ? <p>No learners are enrolled in this course.</p> : <div className="table-scroll"><table>
        <caption>Bulk issuance results</caption>
        <thead><tr><th scope="col">Learner</th><th scope="col">Outcome</th><th scope="col">Details</th></tr></thead>
        <tbody>{result.outcomes.map(outcome => <tr key={outcome.enrollmentId}><td>{outcome.learnerName}</td><td>{outcome.status}</td><td>{outcome.status === 'issued' ? outcome.serialNumber : reasons[outcome.reason]}</td></tr>)}</tbody>
      </table></div>)}
    </>}
  </section>;
}
import { useEffect, useState, type FormEvent } from 'react';
import { isCertificateListResponse, type CertificateListResponse, type CertificateSortField } from '@training/shared';

interface CertificateListProps { token: string; onTokenChange: (token: string) => void; refreshKey: number }
export function CertificateList({ token, onTokenChange: setToken, refreshKey }: CertificateListProps) {
  const [credential, setCredential] = useState('');
  const [draft, setDraft] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [sortBy, setSortBy] = useState<CertificateSortField>('issuedAt');
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('desc');
  const [result, setResult] = useState<CertificateListResponse | null>(null);
  const [state, setState] = useState<'idle' | 'loading' | 'ready' | 'error' | 'unauthorized'>('idle');
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    setResult(null);
    if (!token) { setState('idle'); return; }
    const controller = new AbortController();
    let active = true;
    const timeout = setTimeout(() => controller.abort(), 10000);
    setState('loading');
    const params = new URLSearchParams({ search, page: String(page), pageSize: String(pageSize), sortBy, sortDirection });
    void fetch(`/api/certificates?${params}`, { headers: { Authorization: `Bearer ${token}` }, signal: controller.signal })
      .then(async response => {
        if (response.status === 401) { if (active) setState('unauthorized'); return; }
        if (!response.ok) throw new Error('Certificate request failed');
        const data: unknown = await response.json();
        if (!isCertificateListResponse(data)) throw new Error('Invalid certificate response');
        if (active) { setResult(data); setState('ready'); }
      }).catch(() => { if (active) setState('error'); }).finally(() => clearTimeout(timeout));
    return () => { active = false; controller.abort(); clearTimeout(timeout); };
  }, [token, search, page, pageSize, sortBy, sortDirection, attempt, refreshKey]);
  function applyToken(event: FormEvent) {
    event.preventDefault(); setResult(null); setToken(credential.trim()); setCredential(''); setPage(1); setAttempt(value => value + 1);
  }
  function submitSearch(event: FormEvent) { event.preventDefault(); setSearch(draft.trim()); setPage(1); }
  const pages = result ? Math.max(1, Math.ceil(result.total / pageSize)) : 1;
  return <section aria-labelledby="certificates-heading">
    <h2 id="certificates-heading">Certificates</h2>
    <p>Search issued certificates by learner name or full serial number. Revoked certificates remain in the list.</p>
    <details open={!token}><summary>API token</summary>
      <form onSubmit={applyToken} className="controls">
        <label>Generated admin token<input type="password" value={credential} onChange={event => setCredential(event.target.value)} autoComplete="off" required minLength={43} maxLength={43} /></label>
        <button type="submit">Use token</button>
        {token && <button type="button" onClick={() => { setToken(''); setResult(null); }}>Clear token</button>}
      </form>
      <p>Use your tenant admin token from the demo seed. The token stays in memory and is cleared on reload.</p>
    </details>
    <form onSubmit={submitSearch} className="controls" role="search">
      <label>Learner name or certificate serial number<input value={draft} onChange={event => setDraft(event.target.value)} maxLength={200} type="search" /></label>
      <button type="submit" disabled={!token}>Search</button>
      <button type="button" disabled={!token} onClick={() => { setDraft(''); setSearch(''); setPage(1); }}>Clear search</button>
    </form>
    <div className="controls">
      <label>Sort by<select value={sortBy} onChange={event => { setSortBy(event.target.value as CertificateSortField); setPage(1); }}>
        <option value="issuedAt">Issuance time</option><option value="learnerName">Learner name</option><option value="serialNumber">Serial number</option><option value="courseTitle">Course</option>
      </select></label>
      <label>Sort direction<select value={sortDirection} onChange={event => { setSortDirection(event.target.value as 'asc' | 'desc'); setPage(1); }}><option value="desc">Descending</option><option value="asc">Ascending</option></select></label>
      <label>Rows per page<select value={pageSize} onChange={event => { setPageSize(Number(event.target.value)); setPage(1); }}>{[10, 20, 50, 100].map(size => <option key={size} value={size}>{size}</option>)}</select></label>
    </div>
    <p role="status" aria-live="polite">{state === 'idle' ? 'Supply a generated admin token to load certificates.' : state === 'loading' ? 'Loading certificates…' : state === 'ready' ? `${result?.total ?? 0} certificates found.` : ''}</p>
    {state === 'unauthorized' && <p role="alert">The admin token is invalid or no longer authorized. Supply a valid token.</p>}
    {state === 'error' && <div role="alert">Unable to load certificates. <button onClick={() => setAttempt(value => value + 1)}>Retry certificates</button></div>}
    {state === 'ready' && result && <>
      {result.items.length === 0 ? <p>{result.total === 0 ? 'No certificates match your search.' : 'No certificates on this page. Return to an earlier page.'}</p> : <div className="table-scroll"><table>
        <caption>Issued certificates</caption>
        <thead><tr><th scope="col">Serial number</th><th scope="col">Learner</th><th scope="col">Course</th><th scope="col">Issue date</th><th scope="col">Status</th></tr></thead>
        <tbody>{result.items.map(item => <tr key={item.id}><td className="serial">{item.serialNumber}</td><td>{item.learnerName}</td><td>{item.courseTitle}</td><td>{item.issueDate}</td><td>{item.status === 'active' ? 'Active' : 'Revoked'}</td></tr>)}</tbody>
      </table></div>}
      <nav aria-label="Certificate pagination" className="controls">
        <button disabled={page <= 1} onClick={() => setPage(value => value - 1)}>Previous page</button>
        <span>Page {page} of {pages}</span>
        <button disabled={page >= pages} onClick={() => setPage(value => value + 1)}>Next page</button>
        {page > pages && <button onClick={() => setPage(1)}>First page</button>}
      </nav>
    </>}
  </section>;
}
